---@class ChaoticRecallDojo
local ChaoticRecallDojo = Class("ChaoticRecallDojo")

function ChaoticRecallDojo:__init()
    self.scheduleId = 0   ---排期Id
    self.remainTime = 0   ---剩余秒数
    self.groups = {}       ---分组列表  {groupId 分组id ，starReceived 已领取星级奖励list  ， nodes 节点列表 {nodeId 节点Id, passed 是否通关  starCompleted 已完成星级挑战list[1,2,3],teamInfo} }
    self.bossRemainTime = 0 ---Boss活动剩余时间
end

---FillVo
---@param jsonData table
function ChaoticRecallDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            self[key] = value
        end
    end

    if rawget(jsonData,"remainTime") then
        if self.remainTime > 0 then
            self:UpdateRemainTime(jsonData.remainTime)
        end
    end
    
    if rawget(jsonData,"bossRemainTime") then
        if self.bossRemainTime > 0 then
            self.bossRemainTime = self.bossRemainTime + os.time()
        end
    end

    if rawget(jsonData,"groups") then
        if not isNull(self.groups) then
            self:UpdateGroups()
        end
    end
end

function ChaoticRecallDojo:UpdateGroups()
    for i, v in pairs(self.groups) do
        for k, j in pairs(v.nodes) do
            j.teamInfo = self:InitCardData(j.teamInfo)
        end
    end
end

function ChaoticRecallDojo:GetBossRemainTime()
    return self.bossRemainTime - os.time()
end


function ChaoticRecallDojo:UpdateRemainTime(remainTime)
    self.remainTime = remainTime + os.time()
end

function ChaoticRecallDojo:GetGroups()
    return self.groups
end

function ChaoticRecallDojo:UpdateTeamCardsInfo(groupId, index, cardTab, teamIndex)
    local cardsData = {}
    ---噩梦回想 如果在羁绊中需要下掉
    ---提前当前编队中的卡
    local playerCardId2IsExist = {}
    for _k, memberData in pairs(cardTab) do
        local dojo = CfUtils.GetTeamMemberDojo(memberData)
        table.insert(cardsData, dojo)
        playerCardId2IsExist[checkNumber(dojo.refId)] = true
    end

    for i, v in pairs(self.groups) do
        if checkNumber(v.groupId) == checkNumber(groupId) then
            if not isNull(v.nodes[index]) and not isNull(v.nodes[index].teamInfo) then
                ---移除被当前编队使用的羁绊卡 
                local teamInfo = v.nodes[index].teamInfo
                for _, teamMemberData in pairs(teamInfo) do
                    local cardsInfo = teamMemberData.cardsInfo
                    for _, memberData in pairs(cardsInfo) do
                        if playerCardId2IsExist[memberData.fettersId] then
                            memberData.fettersId = 0
                            memberData.fettersCardId = 0
                        end
                    end
                end

                if v.nodes[index].teamInfo[teamIndex] and v.nodes[index].teamInfo[teamIndex].cardsInfo then
                    v.nodes[index].teamInfo[teamIndex].cardsInfo = cardsData
                else
                    local catsInfo = (not isNull(v.nodes[index].teamInfo[teamIndex]) and not isNull(v.nodes[index].teamInfo[teamIndex].catsInfo)) and v.nodes[index].teamInfo[teamIndex].catsInfo
                    v.nodes[index].teamInfo[teamIndex] = {cardsInfo = cardsData,catsInfo = catsInfo or {} }
                end
            end
        end
    end
end

function ChaoticRecallDojo:UpdateTeamCatsInfo(groupId, index, catTab, teamIndex)
    local catsData = {}
    for key, catData in pairs(catTab) do
        local dojo = CfUtils.GetTeamCatDojo(catData,true, key)
        table.insert(catsData, dojo)
    end

    for i, v in pairs(self.groups) do
        if checkNumber(v.groupId) == checkNumber(groupId) then
            if not isNull(v.nodes[index]) and not isNull(v.nodes[index].teamInfo) then
                if v.nodes[index].teamInfo[teamIndex] and v.nodes[index].teamInfo[teamIndex].catsInfo then
                    v.nodes[index].teamInfo[teamIndex].catsInfo = catsData
                else
                    local cardsInfo = (not isNull(v.nodes[index].teamInfo[teamIndex]) and not isNull(v.nodes[index].teamInfo[teamIndex].cardsInfo)) and v.nodes[index].teamInfo[teamIndex].cardsInfo
                    v.nodes[index].teamInfo[teamIndex] = {catsInfo = catsData, cardsInfo = cardsInfo or {} }
                end
            end
        end
    end
end

function ChaoticRecallDojo:GetRankInfo(index)
    return self.groups[index].topRank
end

function ChaoticRecallDojo:GetMyRank(index)
    return self.groups[index].myRanking
end


function ChaoticRecallDojo:InitCardData(teamData)
    local data = {}
    local teams = checkTable(teamData)
    for _teamKey, teamData in pairs(teams) do
        local t = {}
        t.cardsInfo = {}
        teamData = checkTable(teamData)
        if teamData.cardsInfo then
            for _k, memberData in pairs(teamData.cardsInfo) do
                local dojo = CfUtils.GetTeamMemberDojo(memberData)
                table.insert(t.cardsInfo, dojo)
            end
            data[checkNumber(_teamKey)] = t
        end

        --- 初始化猫编队数据
        local catsInfo = {}
        if teamData.catsInfo then
            local temp = checkTable(teamData.catsInfo)

            for key, value in pairs(temp) do
                ---@type TeamCatBallDojo
                local dojo = CfUtils.GetTeamCatDojo(value, true, key)
                table.insert(catsInfo, dojo)
            end
        end
        t.catsInfo = catsInfo
    end
    return data
end

function ChaoticRecallDojo:GetGroupId(index)
    if self.groups[index] then
        return self.groups[index].groupId
    end
    return nil
end

function ChaoticRecallDojo:GetNodeData(index)
    local data = {}
    local tempData = {}
    if self.groups[index] then
        for i, v in pairs(self.groups[index].nodes) do
            table.insert(tempData,v)
            if i % 2 == 0 then
                table.insert(data,tempData)
                tempData = {}
            end
        end
    end
    ---说明里面有单个的
    if table.count(tempData) > 0 then
        table.insert(data,tempData)
    end

    return data
end

function ChaoticRecallDojo:GetChallengeNodeData(index)
    local data = {}
    if self.groups[index] then
        return self.groups[index].nodes
    end
    return data
end

function ChaoticRecallDojo:IsGetProgressReward(index)
    return checkNumber(self.groups[index].allPassedReceived) == 1
end

function ChaoticRecallDojo:IsGetRankReward(index)
    return checkNumber(self.groups[index].rankReceived) == 1
end

function ChaoticRecallDojo:UpdateRankRewardState(index, state)
    self.groups[index].rankReceived = state
end

function ChaoticRecallDojo:UpdateProgressGetState(index, state)
    self.groups[index].allPassedReceived = state
end

function ChaoticRecallDojo:GetUpGroupData(index)
    return self.groups[index].upGroup
end

function ChaoticRecallDojo:GetUpStarGroupData(index)
    return self.groups[index].starUpGroup
end



function ChaoticRecallDojo:GetUpBuffGroupDataByGroupId(groupId)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6114,"ChaoticRecallTagVo",groupId)
    for i, v in pairs(self.groups) do
        if checkNumber(v.groupId) == groupId then
            if vo.groupType == 1 then
                return self:GetChallengeUpGroup(v.starUpGroup)
            else
                return v.upGroup
            end
        end
    end
    return nil
end

function ChaoticRecallDojo:GetUpGroupDataByGroupId(groupId)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6114,"ChaoticRecallTagVo",groupId)
    for i, v in pairs(self.groups) do
        if checkNumber(v.groupId) == groupId then
            if vo.groupType == 1 then
                return v.starUpGroup
            end
        end
    end
    return nil
end

function ChaoticRecallDojo:GetChallengeUpGroup(groupData)
    local data = {}
    ---@type CardComponent
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    for i, v in ipairs(groupData) do
        local hasCard = cardComp:IsHasCard(v.refId)
        local tempData = {}
        tempData.refId = v.refId
        tempData.type = v.type
        local index = 1
        if hasCard then
            local cardDojo = cardComp:GetCardByConfId(v.refId)
            local star = cardDojo.star
            index = star + 1
        end
        tempData.commonAddId = v.additions[index].commonAddId
        table.insert(data,tempData)
    end
    return data
end

function ChaoticRecallDojo:GetAllNodes(index)
    if self.groups[index] then
        return self.groups[index].nodes
    end
    return nil
end

function ChaoticRecallDojo:GetStarReceiveData(index)
    if self.groups[index] then
        return self.groups[index].starReceived
    end
    return nil
end

function ChaoticRecallDojo:UpdateStarReceive(index,starLevel)
    if self.groups[index] and self.groups[index].starReceived then
        table.insert(self.groups[index].starReceived,starLevel)
    end
end

function ChaoticRecallDojo:UpdateAllStarReceive(index,starReceived)
    if self.groups[index] then
        self.groups[index].starReceived = starReceived
    end
end

function ChaoticRecallDojo:GetAllPassStar(index)
    local count = 0
    for i, v in pairs(self.groups[index].nodes) do
        count = count + table.count(checkTable(v.starCompleted))
    end
    return count
end

function ChaoticRecallDojo:GetRemainTime()
    if self.remainTime > 0  then
        return self.remainTime - os.time()
    end
    return self.remainTime
end

function ChaoticRecallDojo:GetScheduleId()
    return self.scheduleId
end

function ChaoticRecallDojo:__delete()
    self.scheduleId = nil
    self.remainTime = nil
    self.groups = nil
end

return ChaoticRecallDojo